import json,numpy as np
from scipy.spatial.transform import Rotation as Rot
c=json.load(open('/app/output/orientation_cal.json'));b=c[0];R0=np.array(b['camera'])[:3,:3];q0=np.array(b['q']);p0=np.array(b['eef']);J=np.zeros((6,7))
for i in range(7):
 a=c[i+1];dq=np.array(a['q'])[i]-q0[i];J[:3,i]=(np.array(a['eef'])-p0)/dq;J[3:,i]=Rot.from_matrix(np.array(a['camera'])[:3,:3]@R0.T).as_rotvec()/dq
print('q0',q0.round(3));print('p0',p0.round(3));print('J\n',J.round(3));
for target in [[2.205,-.57,1.62],[2.205,-.47,1.55],[2.22,-.43,1.52]]:
 e=np.r_[np.array(target)-p0,[0,0,0]];dq=np.linalg.lstsq(J,e,rcond=.02)[0];print('target',target,'dq',dq.round(3),'q', (q0+dq).round(3),'pred', (J@dq).round(3),'err',np.linalg.norm(J@dq-e))
